canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*canvas.width/r.width,y=(e.clientY-r.top)*canvas.height/r.height;if(droneCommand){drone.tx=x;drone.ty=y;droneCommand=false;burst(x,y,'#ffffff',8);beep(640,.08);renderUI();return;}let nearest=-1,distance=Math.max(46,Math.min(92,28*canvas.width/r.width));PADS.forEach((p,i)=>{const d=Math.hypot(p[0]-x,p[1]-y);if(d<distance){nearest=i;distance=d;}});if(nearest>=0)selectPad(nearest);else if(!ended){selectedPad=-1;renderUI();}});
